create or replace function public.clear_inventory_budget(p_bucket text) returns boolean language plpgsql security definer set search_path = public as $$ declare v_cleared integer; begin if p_bucket is null or p_bucket not like 'inventory-rows:%' then return false; end if; delete from public.rate_limits where bucket = p_bucket; get diagnostics v_cleared = row_count; return v_cleared > 0; end; $$;
comment on function public.clear_inventory_budget(text) is 'Clear one account''s inventory-rows counter, so its next window starts at nothing. Refuses any bucket outside the inventory-rows prefix, so it cannot reach a sign-in throttle. Called by our server when a customer adds a listing to their basket.';
